    // }

    // ✅ CHANGE: This calculation is now fully dynamic, based on the Excel logic.
    const calculateStaffAllocation = (staffMember, role, source) => {
        // Guard against missing data on initial render
        if (!staffMember || !role || !source.perStudentAllocations || !source.activityAllocations) {
            return 0;
        }

        // Part 1: Per-student allocation. Finds the rates for the specific role.
        const perStudentRoleData = source.perStudentAllocations.find(p => p.role === role.name);
        const perStudentFactor = perStudentRoleData ? (perStudentRoleData.marking + perStudentRoleData.consultation + perStudentRoleData.coordination) : 0;
        const perStudentPart = (staffMember.students / 25) * perStudentFactor;

        // Part 2: Per-activity allocation.
        let activitiesPart = 0;
        const workloadMultiplier = 1.0; // Assuming workload multiplier ($G$12) is 1.0

        source.activityAllocations.forEach((activity, index) => {
            const activityId = `activity-${index + 1}`; // Match activity-1, activity-2 etc.
            const numGroupsForStaff = staffMember.groups[activityId] || 0;
            const weeklyClassTime = parseFloat(activity.weeklyClassTime) || 0;

            // Finds the distribution percentages for the specific role within the activity data
            const activityRoleDist = activity.distribution?.[role.name] || {};
            const allocationWeight = (activityRoleDist['Preparation / Setup'] || 0) + (activityRoleDist['Delivery / Supervision'] || 0);

            activitiesPart += (numGroupsForStaff * weeklyClassTime * allocationWeight);
        });

        return perStudentPart + (activitiesPart * workloadMultiplier);
    };

    const coordinatorAllocation = useMemo(() => {
        if (!sourceData.perStudentAllocations || !sourceData.activityAllocations) return 0;

        const totalStudents = sourceData.totalStudents || 0;
        const coordPerStudentData = sourceData.perStudentAllocations.find(p => p.role === 'Subject Coordinator');
        const perStudentFactor = coordPerStudentData ? (coordPerStudentData.marking + coordPerStudentData.consultation + coordPerStudentData.coordination) : 0;
        const perStudentPart = (totalStudents / 25) * perStudentFactor;

        let activitiesPart = 0;
        const workloadMultiplier = 1.0; 

        sourceData.activityAllocations.forEach(activity => {
            const numGroups = parseFloat(activity.numberOfGroups) || 0;
            const weeklyClassTime = parseFloat(activity.weeklyClassTime) || 0;
            const coordDist = activity.distribution?.['Subject Coordinator'] || {};
            const allocationWeight = (coordDist['Preparation / Setup'] || 0) + (coordDist['Delivery / Supervision'] || 0);
            activitiesPart += (numGroups * weeklyClassTime * allocationWeight);
        });

        return perStudentPart + (activitiesPart * workloadMultiplier);
    }, [sourceData]);
